package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import com.ruoyi.common.exception.ServiceException;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** 原Java样本的中心固定引擎/图准入/历史字节边界；不调用Provider或业务库。 */
class JavaToolCompilationPolicyTest {
 private JSONObject source()throws Exception{try(var in=getClass().getResourceAsStream("/paiflow/java-tool/original-java-tool-golden.json")){assertNotNull(in);return JSON.parseObject(new String(in.readAllBytes(),StandardCharsets.UTF_8)).getJSONObject("assignment");}}
 private JSONObject graph(JSONObject source){return new DslCodec().normalize(source.getJSONObject("dsl"),DslCodec.V2).execution();}
 private JSONObject plugin(JSONObject graph){return DataWorkerOperationService.find(graph,"plugin::2");}
 private WorkflowModelCompiler.Compiled compile(JSONObject graph,JSONObject source,AtomicInteger calls,String engine){String resource=source.getJSONObject("resourceSnapshots").keySet().iterator().next();var descriptor=source.getJSONObject("resourceSnapshots").getJSONObject(resource);return WorkflowModelCompiler.compile(graph,(a,b,c)->{fail("Java不能走Python模型目录");return null;},a->{fail("Java不能走数据目录");return null;},(p,v,o,a)->{calls.incrementAndGet();return new ToolRuntimeCatalog.Fixed(resource,descriptor,new JSONObject(),1,2,1,42,"fixture");},engine);}
 @Test void fixedEngineSelectsJavaV2AndPythonV4()throws Exception{var source=source();var graph=graph(source);assertEquals(DslCodec.V2,WorkflowModelCompiler.executionCodecFor(graph,"java"));assertEquals(DslCodec.V4,WorkflowModelCompiler.executionCodecFor(graph,"python"));var calls=new AtomicInteger();var compiled=compile(graph,source,calls,"java");assertEquals(1,calls.get());assertTrue(ToolSchema.same(compiled.execution(),WorkflowModelCompiler.reconstruct(graph,compiled.resourceSnapshots(),DslCodec.V2,"java")));assertEquals(503,assertThrows(ServiceException.class,()->WorkflowModelCompiler.reconstruct(graph,compiled.resourceSnapshots(),DslCodec.V4,"java")).getCode());}
 @Test void normalHandleAndUndeclaredWholeMapArrayReferenceKeepOriginalJavaMeaning()throws Exception{var source=source();var graph=graph(source);graph.getJSONArray("edges").getJSONObject(0).put("sourceHandle","normal_one_of");var ref=DataWorkerOperationService.find(graph,"node-end::3").getJSONObject("data").getJSONArray("inputs").getJSONObject(0).getJSONObject("schema").getJSONObject("value").getJSONObject("content");ref.put("name","data[0].x");assertDoesNotThrow(()->JavaToolGraphPolicy.validate(graph));}
 @Test void missingNullAndNonObjectPluginParametersAreExplicitlyRejectedBeforeResolver()throws Exception{for(Object malformed:Arrays.asList(null,"not-object",new JSONArray())){var source=source();var graph=graph(source);plugin(graph).getJSONObject("data").put("nodeParam",malformed);var calls=new AtomicInteger();assertEquals(422,assertThrows(ServiceException.class,()->compile(graph,source,calls,"java")).getCode());assertEquals(0,calls.get());}}
 @Test void futureReferenceCannotResolveAResource()throws Exception{var source=source();var graph=graph(source);plugin(graph).getJSONObject("data").getJSONArray("inputs").getJSONObject(0).getJSONObject("schema").getJSONObject("value").getJSONObject("content").put("nodeId","node-end::3");var calls=new AtomicInteger();assertEquals(403,assertThrows(ServiceException.class,()->compile(graph,source,calls,"java")).getCode());assertEquals(0,calls.get());}
 @Test void unconnectedRetryFailureRoutingAndOriginalTtsRemainExplicitlyPending()throws Exception{for(String mode:List.of("retry","failure","tts")){var source=source();var graph=graph(source);if("retry".equals(mode))plugin(graph).getJSONObject("data").put("retryConfig",JSONObject.of("shouldRetry",true));if("failure".equals(mode))graph.getJSONArray("edges").getJSONObject(0).put("sourceHandle","intent_chain|fail_one_of");if("tts".equals(mode))plugin(graph).getJSONObject("data").getJSONObject("nodeParam").put("pluginId","tool@8b2262bef821000");var calls=new AtomicInteger();assertEquals(503,assertThrows(ServiceException.class,()->compile(graph,source,calls,"java")).getCode());assertEquals(0,calls.get());}}
 @Test void javaNullAndEmptyVersionsKeepOriginalDefaultButWhitespaceIsNotRebound()throws Exception{for(Object version:Arrays.asList(null,"")){var source=source();var graph=graph(source);plugin(graph).getJSONObject("data").getJSONObject("nodeParam").put("version",version);var compiled=compile(graph,source,new AtomicInteger(),"java");assertEquals("V1.0",plugin(compiled.execution()).getJSONObject("data").getJSONObject("nodeParam").get("version"));}var source=source();var graph=graph(source);plugin(graph).getJSONObject("data").getJSONObject("nodeParam").put("version"," ");var calls=new AtomicInteger();assertEquals(400,assertThrows(ServiceException.class,()->compile(graph,source,calls,"java")).getCode());assertEquals(0,calls.get());}
 @Test void pythonExplicitNullVersionStillRejectsInsteadOfTakingJavaDefault()throws Exception{var source=source();var graph=graph(source);plugin(graph).getJSONObject("data").getJSONObject("nodeParam").put("version",null);var calls=new AtomicInteger();assertEquals(400,assertThrows(ServiceException.class,()->compile(graph,source,calls,"python")).getCode());assertEquals(0,calls.get());}
 @Test void historicalPureJavaV1AndV2ReconstructionKeepsExactOldBytes()throws Exception{var graph=graph(source());graph.getJSONArray("nodes").removeIf(raw->"plugin::2".equals(((JSONObject)raw).get("id")));graph.put("edges",new JSONArray(List.of(JSONObject.of("sourceNodeId","node-start::1","targetNodeId","node-end::3"))));for(String codec:List.of(DslCodec.V1,DslCodec.V2)){var old=WorkflowModelCompiler.reconstruct(graph,new JSONObject(),codec);var current=WorkflowModelCompiler.reconstruct(graph,new JSONObject(),codec,"java");assertEquals(DslCodec.canonicalDslBase64(old,codec),DslCodec.canonicalDslBase64(current,codec));assertEquals(DslCodec.fixedExecutionHash(old,codec),DslCodec.fixedExecutionHash(current,codec));}}
}
